import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiDungeon","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/dungeon/index.md","filePath":"en/modules/dungeon/index.md","lastUpdated":0}`),a={name:`en/modules/dungeon/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakidungeon" tabindex="-1">EmakiDungeon <a class="header-anchor" href="#emakidungeon" aria-label="Permalink to “EmakiDungeon”">​</a></h1><p>EmakiDungeon is a party dungeon plugin: you team up, pick a difficulty, clear a <strong>private dungeon world</strong> together, and claim the loot</p><ul><li>Every party gets its own world <strong>cloned from the template</strong>, so runs never interfere with each other, and the world is deleted as soon as the run ends</li><li>The dungeon ships with a complete challenge flow: first pick the difficulty and drop mode, then confirm ready, wait out the world preparation countdown, and enter</li><li>Entry limits are managed per day / week / month, with challenge time windows, weekdays, week-of-month, and cooldown support</li><li>Routed rewards go into a <strong>stash</strong> first and are only paid out on clear; leaving mid-run or failing voids everything, and player state rolls back to a snapshot taken on entry</li><li>Built-in party system (invite / apply / kick / party channel); in-dungeon chat is isolated from global chat by default, and you can toggle global listening any time</li><li>Built-in <strong>map editor</strong>: mark regions, place markers, fill blocks, run a test start in game, and write back to the template on save</li><li>The run is described by <code>flow.yml</code>: rooms, waves, gates, branch options, trigger zones, timers, kill targets, and 22 module types in total</li><li>GraalJS dungeon scripts and CoreLib action pipelines let you hook custom logic to dungeon lifecycle events</li></ul><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to “Basics”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.0.13</code></td></tr><tr><td>Build artifact</td><td><code>EmakiDungeon-1.0.13.jar</code></td></tr><tr><td>API coordinate</td><td><code>emaki.jiuwu.craft:emaki-dungeon-api:1.0.3</code> (compile-time only, never put it into <code>plugins/</code>)</td></tr><tr><td>Main command</td><td><code>/edg</code> (aliases <code>/dungeon</code>, <code>/edungeon</code>)</td></tr><tr><td>Required dependency</td><td>EmakiCoreLib (<code>required: true</code>, <code>join-classpath: true</code>)</td></tr><tr><td>Optional dependencies</td><td>MythicMobs, WorldGuard (everything works without them; the matching integrations just stay off)</td></tr><tr><td>Permission nodes</td><td><code>emakidungeon.play</code>, <code>emakidungeon.dungeon.*</code>, <code>emakidungeon.bypass.limit</code>, <code>emakidungeon.bypass.escape</code>, <code>emakidungeon.script</code>, <code>emakidungeon.editor</code>, <code>emakidungeon.admin</code>, <code>emakidungeon.*</code></td></tr><tr><td>Supported platforms</td><td>Paper 26.1+, Folia supported (<code>folia-supported: true</code>)</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Every dungeon also gets a dynamically registered permission <code>emakidungeon.dungeon.&lt;dungeonId&gt;</code> whose default is <strong>open to all players</strong>; to make a dungeon members-only, flip that default off in your permission plugin and grant it to the groups you want</p></div><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Player commands, party subcommands, editor session commands, admin commands, and the permission table</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>Every key of the global <code>config.yml</code>, the per-dungeon <code>config.yml</code>, and the reward box GUI</td></tr><tr><td><a href="./challenges.html">Challenges &amp; Rewards</a></td><td>Entry flow, entry limits, party rules, reward stash and payout, failure rollback</td></tr><tr><td><a href="./flow.html">Flow &amp; Triggers</a></td><td>The 22 module types of <code>flow.yml</code>, editor workflow, lifecycle actions, and scripts</td></tr><tr><td><a href="./api.html">API</a></td><td>For developers: the <code>emaki-dungeon-api</code> facades and every event</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core capabilities”">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>Instance world pool</td><td>Worlds are cloned from templates, one spare world is kept warm per dungeon (<code>pool.max-worlds</code>, global <code>limit.max-instances</code>); worlds are created on demand and deleted on dispose, and startup self-checks clean up leftovers</td></tr><tr><td>Challenge flow</td><td>Leader starts, difficulty select, drop-mode select, full-party ready confirmation (times out to cancel), world preparation wait (bossbar or chat, cancellable), then entry counts against limits</td></tr><tr><td>Three-tier entry limits</td><td>Daily / weekly / monthly counts with challenge windows, evaluated in the order month &gt; week &gt; day, plus a standalone cooldown; counters bucket by server timezone or <code>general.timezone</code></td></tr><tr><td>Reward stash and payout</td><td>Routed loot is stashed during the run and paid into the reward box or inventory on clear using the chosen drop mode; failing voids the stash and restores the player snapshot</td></tr><tr><td>Party and chat isolation</td><td>Party size and invite mode are configurable; dungeon chat stays inside the instance unless the player runs <code>/edg globalchat on</code>, and the party channel is separate</td></tr><tr><td>Command guard</td><td>Commands inside a dungeon pass a blacklist/whitelist filter, escape commands (like <code>/tp *</code>) sit in a separate blacklist that no allow-rule can override, and players crossing the boundary are pulled back</td></tr><tr><td>Map editor</td><td>A separate edit world with two-point regions, six marker types, area fill, panel field editing, test start (no counts, no leaderboard), write-back only on save</td></tr><tr><td>Scoring and ranking</td><td>Five weights (damage, kills, heal, deaths, defense) feed the score, plus per-dungeon leaderboards and personal stats</td></tr><tr><td>Lifecycle actions</td><td>11 lifecycle segments (from <code>dungeon_enter</code> to <code>dungeon_destroy</code>) run through the CoreLib action pipeline for broadcasts, sounds, and custom logic</td></tr><tr><td>Runtime monitors</td><td>Alert thresholds for MSPT P95, heap slope, and write-queue backlog (threshold <code>&lt;= 0</code> disables), reported to console and the audit log</td></tr></tbody></table><h2 id="default-configuration-layout" tabindex="-1">Default configuration layout <a class="header-anchor" href="#default-configuration-layout" aria-label="Permalink to “Default configuration layout”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiDungeon/</span></span>
<span class="line"><span>├── config.yml               ← main configuration (global switches and limits)</span></span>
<span class="line"><span>├── world/</span></span>
<span class="line"><span>│   └── &lt;dungeonId&gt;/</span></span>
<span class="line"><span>│       ├── config.yml       ← per-dungeon config (auto-generated when missing)</span></span>
<span class="line"><span>│       ├── flow.yml         ← flow definition (auto-generated when missing)</span></span>
<span class="line"><span>│       └── region/          ← dungeon map region files</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   └── rewardbox.yml        ← reward box GUI (pages and capacity)</span></span>
<span class="line"><span>├── scripts/                 ← GraalJS dungeon scripts, file name = &lt;dungeonId&gt;.js (optional)</span></span>
<span class="line"><span>├── instances.yml            ← runtime instance records (auto-generated, do not edit)</span></span>
<span class="line"><span>├── parties.yml              ← party snapshots (auto-generated, do not edit)</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p>A dungeon template is simply a folder under <code>world/</code>, and the folder name is the dungeon ID. On startup and on <code>/edg admin reload</code> the plugin scans that directory and fills in a missing <code>config.yml</code> or <code>flow.yml</code> from the bundled templates, without overwriting existing files</p><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to “Typical workflow”">​</a></h2><ol><li>First create a folder under <code>plugins/EmakiDungeon/world/</code> as the dungeon ID (for example <code>my_dungeon</code>) and drop your map region files into it (or start empty and build with the editor)</li><li>Restart the server or run <code>/edg admin reload</code>; the missing <code>config.yml</code> and <code>flow.yml</code> are generated for you</li><li>Run <code>/edg editor my_dungeon</code>, place markers, wire the flow, and click &quot;Save and write back&quot; when done</li><li>Then tune difficulty, entry limits, and drop modes in <code>config.yml</code>, and run <code>/edg admin reload</code> again</li><li>Players run <code>/edg list</code> to see dungeons and <code>/edg enter my_dungeon</code> to start; the leader picks a difficulty and everyone confirms readiness</li><li>On clear, open the reward box (<code>/edg rewards</code>), or turn the reward box off in config to send payouts straight to the inventory</li></ol><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to “Related modules”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>How it fits</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td>Required dependency: scheduling, messages, config checks, and the action pipeline; dungeon lifecycle actions run as CoreLib action segments</td></tr><tr><td>EmakiMobs</td><td>Spawn waves can reference EmakiMobs definitions with the <code>emakimobs:</code> prefix (vanilla entity ids work without it)</td></tr><tr><td>EmakiItem / EmakiLevel</td><td>The settlement command chain <code>settlement.commands</code> can call their commands to grant items and experience</td></tr><tr><td>MythicMobs / WorldGuard</td><td>Optional dependencies; the plugin runs normally without them and the matching integrations stay off</td></tr></tbody></table>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};